UPDATE store_delivery_people p SET name=v.name FROM (VALUES ('SAMPLE-01','Arun Kumar'),('SAMPLE-02','Karthik Raj'),('SAMPLE-03','Vijay Anand'),('SAMPLE-04','Suresh Kumar'),('SAMPLE-05','Dinesh Ravi'),('SAMPLE-06','Praveen Raj'),('SAMPLE-07','Rahul Sharma'),('SAMPLE-08','Arjun Patel'),('SAMPLE-09','Sanjay Kumar'),('SAMPLE-10','Deepak Singh'),('SAMPLE-11','Naveen Kumar'),('SAMPLE-12','Vignesh Raj'),('SAMPLE-13','Saravanan'),('SAMPLE-14','Manoj Kumar'),('SAMPLE-15','Ashok Raj'),('SAMPLE-16','Bala Murugan'),('SAMPLE-17','Hari Prasad'),('SAMPLE-18','Ganesh Kumar'),('SAMPLE-19','Ramesh Babu'),('SAMPLE-20','Rajesh Kumar'),('SAMPLE-21','Yuya Sato'),('SAMPLE-22','Haruto Tanaka'),('SAMPLE-23','Kaito Suzuki'),('SAMPLE-24','Ren Takahashi'),('SAMPLE-25','Yuto Watanabe'),('SAMPLE-26','Wei Chen'),('SAMPLE-27','Jun Li'),('SAMPLE-28','Ming Zhang'),('SAMPLE-29','Hao Wang'),('SAMPLE-30','Tao Liu')) AS v(code,name) WHERE p.code=v.code AND p.sample=true AND p.name LIKE 'Sample courier %';
UPDATE store_order_details d SET payload=jsonb_set(d.payload,'{deliveryPerson,name}',to_jsonb(p.name)) FROM store_delivery_people p WHERE d.payload->'deliveryPerson'->>'id'=p.id::text AND d.payload->'deliveryPerson'->>'sample'='true' AND p.sample=true;
